SELECT student_name, student_email, completion_percentage FROM enrollments WHERE course_title = 'Intro to Python';
SELECT * from enrollments WHERE completion_percentage < 10;
SELECT * from enrollments WHERE instructor is NULL;
SELECT student_name, student_id, completion_percentage from enrollments ORDER BY completion_percentage desc LIMIT 5; 
SELECT * from enrollments WHERE enrollment_date >= '2024-07-01' ORDER BY enrollment_date DESC;
INSERT INTO enrollments (id, student_id, student_name, student_email, course_id, course_title, category, enrollment_date, completion_percentage, passed, monthly_fee_paid, instructor) VALUES (18,  3, 'Lucia Fernandes',   'lucia.fernandes@student.edutrack.com', 5, 'Advanced Python',      'Programming',      '2025-04-01',  0, FALSE, 69.99, 'Carlos Vega');
UPDATE enrollments SET instructor = 'Pending assignment' WHERE instructor is null;
DELETE from enrollments where student_email LIKE '%test.com';
SELECT category, COUNT(*) AS row_count FROM enrollments GROUP BY category;
SELECT course_title, AVG(completion_percentage) AS average_completion FROM enrollments GROUP BY course_title;
SELECT course_title, COUNT(id) AS total_enrollments FROM enrollments GROUP BY course_title HAVING COUNT(id) > 3;
SELECT category, SUM(monthly_fee_paid) AS total_revenue FROM enrollments GROUP BY category ORDER BY total_revenue DESC;
